<?php require __DIR__ . '/_bootstrap.php'; $modules = $db->prepare('SELECT m.*, s.libelle AS semestre, n.libelle AS niveau, f.libelle AS formation FROM module m INNER JOIN semestre s ON s.idSemestre=m.idSemestre INNER JOIN niveau n ON n.idNiveau=s.idNiveau INNER JOIN formation f ON f.idFormation=n.idFormation WHERE m.idFormateur=:id ORDER BY f.libelle,n.ordre,s.ordre,m.libelle'); $modules->execute(['id'=>$formateurId]); $modules=$modules->fetchAll(); $pageTitle='Mes modules'; $activeMenu='modules'; require __DIR__ . '/../../includes/header.php'; ?>
<div class="director-heading"><div><h2>Mes modules</h2><p><?=count($modules)?> module(s) affecté(s).</p></div></div><div class="card" style="overflow-x:auto"><table class="director-table"><thead><tr><th>Formation</th><th>Niveau</th><th>Semestre</th><th>Module</th><th>Volume</th></tr></thead><tbody><?php foreach($modules as $module): ?><tr><td><?=htmlspecialchars($module['formation'])?></td><td><?=htmlspecialchars($module['niveau'])?></td><td><?=htmlspecialchars($module['semestre'])?></td><td><strong><?=htmlspecialchars($module['libelle'])?></strong></td><td><?= (int)$module['volumeHoraire'] ?> h</td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__ . '/../../includes/footer.php'; ?>